from taf.sw.dcap.rd.provider import DcapProvider


class DcapConnection(object):
    def __init__(self, host, port, username=None, password=None, rd_version='dcapv3', secure=False, timeout=60):
        """
        Provides connection to DCAP-LITE.

        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: Port for connection to DCAP.
        :param str username: username, default value: None. If user wants to connect DCAP with username
                             please update 'username'='dcapuser'.
        :param str password: password, default value: None. If user wants to connect DCAP with password
                             please update 'password'=dcapadmin!.
        :param str rd_version: RD version used in this library, default value is `dcapv3`
                               If user wants to run keywords from v2 version please pass rd_version=`dcapv2`
                               If user wants to run keywords from v3 version please pass rd_version=`dcapv3`
                               would suggest to use the latest version as those provide more info.
        :param bool secure: If set to `True`, the connection will be realized with use https prefix,
                            else with http, default value is `False`.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns DcapConnection instance.
        """
        self._rd = DcapProvider.create_dcap(host=host,
                                            port=port,
                                            username=username,
                                            password=password,
                                            rd_version=rd_version,
                                            secure=secure,
                                            timeout=timeout)

    def create_bts(self, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='test_bts',
                   credential_region_Id='DEFAULT_CREDENTIALS', timeout=30):
        """
        This method is used to create the bts under DCAP-LITE

        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: (optional) Port for connection to DCAP, default value is `443`
        :param str username: (optional) Username to authenticate the BTS, default value is `Nemuadmin`
        :param str password: (optional) Password to authenticate the BTS, default value is `nemuuser`
        :param str bts_alias: (optional) alias for bts, default value is `target_bts`
        :param str credential_region_Id: (optional) Unique identifier for credential region,
                                         default value is `DEFAULT_CREDENTIALS`
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return self._rd.create_bts(host, port, username, password, bts_alias, credential_region_Id, timeout)

    def create_multiple_bts(self, bts_info, timeout=30):
        """
        This method is used to create multiple bts under DCAP-LITE

        :param array bts_info: An array of dict containing the following fields:
        * **host** (*str*) - The host name of the BTS.
        * **port** (*int*) - The port number used for the BTS connection.
        * **username** (*str*) - The username used for the BTS connection.
        * **password** (*str*) - The password used for the BTS connection.
        * **alias** (*str*) - The alias used for the BTS connection.

        Example usage:

        .. code-block:: python

        bts_info = [{'host': '10.0.0.1', 'port': 22, 'username': 'user1', 'password': 'password1'},
                    {'host': '10.0.0.2', 'port': 22, 'username': 'user2', 'password': 'password2'}]

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return self._rd.create_multiple_bts(bts_info, timeout)

    def delete_bts(self, bts_id=None, timeout=30):
        """
        This method is used to delete the bts under DCAP-LITE

       :param str bts_id: bts id which has to be deleted. Id will be returned from create_bts keyword.
       :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: 'OK'.
        """
        return self._rd.delete_bts(bts_id=bts_id, timeout=timeout)

    def edit_bts(self, bts_id, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='test_run',
                 lte_cells=None, nr_cells=None, timeout=30):
        """
        This method is used to create the bts under DCAP-LITE

        :param float or int bts_id: (required)
        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: Port for connection to DCAP, default value is `443`
        :param str username: Username to authenticate the BTS, default value is `Nemuadmin`
        :param str password: Password to authenticate the BTS, default value is `nemuuser`
        :param str bts_alias: alias for bts, default value is `target_bts`
        :param str lte_cells: Sets the lte_cells
        :param str nr_cells: Sets the nr_cells
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return self._rd.edit_bts(bts_id=bts_id, host=host, port=port, username=username, password=password,
                                 bts_alias=bts_alias, lte_cells=lte_cells, nr_cells=nr_cells, timeout=timeout)

    def delete_trace(self, trace_id=None, timeout=30):
        """
        This method is used to delete the bts trace under DCAP-LITE

        :param str trace_id: trace id which has to be deleted. Id will be returned from start_trace keyword.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: 'OK'.
        """
        return self._rd.delete_trace(trace_id=trace_id, timeout=timeout)

    def start_trace(self, tag='start_trace', duration=-1, bts=None, timeout=400, resource_group=None,
                    allow_start_failures=True, force=True, **kwargs):
        """
        This method is used to start trace under DCAP-LITE

        :param dict bts: (required) dict of bts details containing host, username, password and port number to
                          start the trace for single bts.
                          The list of dict bts details containing host, username, password and port number to
                          start the trace for multiple bts.
        :param str tag: the tag of this StartTraceBody. default 'start_trace'
        :param float duration: The duration of this StartTraceBody duration in minutes.default infinite duration
        :param Union[int,str] timeout: (optional) Timeout to wait for "running" state, default=400s
        :param str kwargs:  supported params are as below:
        :param bool force: signifying whether the trace should force a shutdown of any previously running traces.
                       Defaults to true. If the trace startup finds an ongoing trace and 'force' is set to false,
                       the startup fails due to ongoing traces error. If the 'force' flag is set to true,
                       the startup first shuts down any ongoing traces and then continues with the startup,
                       default value is "True"
        :param str gnb_trace_profile: the id or name of the gNB (5G) start trace. user can get the gNB trace profile
                                      id or name details from `get_5g_profiles`.
        :param str enb_trace_profile: the id or name of the LTE (ENB) start trace. user can get the LTE trace profile
                                      id or name details from  `get_LTE_profiles`.
        :param str bts_trace_profile: the id or name of the BTS start trace. user can get the BTS trace profile
                                      id or name details from  `get_bts_profiles`.
        :param str vcu_trace_profile: the id or name of the vCU start trace. user can get the vCU trace profile
                                      id or name details from  `get_vcu_profiles`.
        :param str vdu_trace_profile: the id or name of the vDU start trace. user can get the vDU trace profile
                                      id or name details from  `get_vdu_profiles`.
        :param list gnb_custom_profile: The gNB (5G) custom profile name list of the start trace to be started.

                                         e.g : [pmFiles5g, condor5gSyslog, SCF5g,
                                         L2Ps_Component, L2Lo_Component, L2HiRlc_Component, L2HiPdcp_Component,
                                         L2Ps_Sherpa, L2Lo_Sherpa, L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         Tracer_5g,
                                         :ref:`l1IqTracer <l1IqTracer>`,
                                         :ref:`cp_5g <controlPlane5g>`,
                                         :ref:`controlPlane5g <controlPlane5g>`,
                                         :ref:`bip_interface_mirroring <bip_interface_mirroring>`,
                                         :ref:`L1stream <L1stream>`,
                                         :ref:`L2Ps_Component <L2Ps_Component>`]

        :param list enb_custom_profile: The LTE (ENB) custom profile name list of the start trace to be started.

                                         e.g : [lteTracer_4g, condor4gTti, condor4gAa, condor4gSyslog,
                                         pmFiles4g, scf4g, condor4gL2, l1Iq4g,
                                         :ref:`cp_4g <controlPlane4g>`,
                                         :ref:`controlPlane4g <controlPlane4g>`]

        :param list bts_custom_profile: The BTS custom profile name list of the start trace to be started.

                                         e.g : [scf, pmFiles,
                                         :ref:`rad <rad>`,
                                         :ref:`tss <tss>`,
                                         :ref:`immediateSnapshot <immediateSnapshot>`,
                                         :ref:`ipCapture <ipCapture>`,
                                         :ref:`screlBts <screlBts>`,
                                         :ref:`BTSeventBasedTracer <BTSeventBasedTracer>`]


        :param list vdu_custom_profile: The VDU custom profile name list of the start trace to be started.

                                         e.g : [snapshotVdu, tracerVdu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`L1StreamVdu <L1StreamVdu>`
                                         :ref:`flowTracerVdu <controlPlane5gVdu>`,
                                         :ref:`tssVdu <tssVdu>`,
                                         :ref:`controlPlane5gVdu <controlPlane5gVdu>`,
                                         :ref:`syslogVdu <syslogVdu>`,
                                         :ref:`l1IqVdu <l1IqVdu>`,
                                         :ref:`eventBasedTracerVdu <eventBasedTracerVdu>`,
                                         :ref:`screlVdu <screlVdu>`]

        :param list vcu_custom_profile: The VCU custom profile name list of the start trace to be started.
                                         e.g : [snapshotVcu, tracerVcu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`flowTracerVcu <controlPlane5gVcu>`
                                         :ref:`controlPlane5gVcu <controlPlane5gVcu>`,
                                         :ref:`syslogVcu <syslogVcu>`,
                                         :ref:`screlVcu <screlVcu>`]

        :param bool wait_for_activation: If user wants to confirm if the traces are started, and it is in "running"
                                    state. pass wait_for_activation=True
        :param str resource_group: 	you can pass "on-demand" or "inspector"
        :param bool allow_start_failures: If set to true trace will continue even on tracer errors, as long as one
                                          trace target is running. If set to false whole trace will fail if even single
                                          tracer fails. default value is "True"
        :param post_processors: (optional) by default false.
                                For emil decoding pass post_processors=True and emil_profile_values
                                The profiles can be "standard" Emil profile (like "5G L3") or custom, user created
                                profile? e.g. emil_profile_values='5G L3'

        :return: It returns start trace tracer_id
        """
        return self._rd.start_trace(tag=tag, duration=duration, bts=bts, resource_group=resource_group,
                                    allow_start_failures=allow_start_failures, force=force,
                                    timeout=timeout, **kwargs)

    def stop_trace(self, trace_id=None, timeout=60):
        """
        This method is used to stop trace under DCAP-LITE

        :param str trace_id: trace id which has to be stopped. Id will be returned from start_trace keyword.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: custom_filter_file, force, tag, bts, trace_profiles,
                 and duration.
        """
        return self._rd.stop_trace(trace_id=trace_id, timeout=timeout)

    def get_results(self, timeout=100, result_id=None, target_file_name=None, target_dir=None):
        """
        This method is used to download the trace file under DCAP-LITE

        :param str result_id: result id to get the trace downloaded path. Id will be returned from start_trace keyword.
        :param str target_dir: (optional) local storage path for collected files, default path will be /tmp
        :param str target_file_name: (optional) target file name to save the trace file, default file name will be
                                     UTFLab_start_time.zip
        :param Union[int,str] timeout: Timeout to wait for 'ready' or 'failed' or 'failedToStop' state, default=100s

        :return: filepath.
        """
        return self._rd.get_results(result_id=result_id, target_dir=target_dir, target_file_name=target_file_name,
                                    timeout=timeout)

    def get_result_file_contents(self, result_id=None, timeout=60):
        """
        This method is used to get result file contents under DCAP-LITE

        :param str result_id: result id to get the trace contents. Id will be returned from start_trace keyword.
        :param Union[int,str] timeout: Timeout to wait for 'ready' or 'failed' or 'failedToStop' state, default=100s

        :return: dict object.
        """
        return self._rd.get_result_file_contents(result_id=result_id, timeout=timeout)

    def get_result_file(self, file_path_in_zip, result_id=None, target_dir=None, target_file_name=None,
                        timeout=100):
        """
        This method is used to get result file contents under DCAP-LITE

        :param str file_path_in_zip: user can get the file_path_in_zip path name from
                   `get_result_file_contents` keyword e.g. "logs/dcap-lite-kong.log"
        :param str result_id: result id to get the trace contents as per the file_path_in_zip arg.
                   Id will be returned from start_trace keyword.
        :param str target_dir: (optional) local storage path for collected files, default path will be /tmp
        :param str target_file_name: (optional) target file name to save the trace file, default file name will be
                                     according to file_path_in_zip
        :param Union[int,str] timeout: Timeout to wait for 'ready' or 'failed' or 'failedToStop' state, default=100s

        :return: filepath.
        """
        return self._rd.get_result_file(file_path_in_zip=file_path_in_zip, result_id=result_id,
                                        target_dir=target_dir, target_file_name=target_file_name,
                                        timeout=timeout)

    def get_trace_info_by_id(self, trace_id=None, timeout=30):
        """
        This method is used to get the trace info under DCAP-LITE

        :param str trace_id: trace id to get the info by id. Id will be returned from start_trace keyword.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: id, duration, initTime, startTime, statusDetails
                 statusMessages, traceProfiles, resultsAvailable, resultSizeInBytes, tag and targets.
        """
        return self._rd.get_trace_info_by_id(trace_id=trace_id, timeout=timeout)

    def get_all_trace_info(self, timeout=30):
        """
        This method is used to get all the trace info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: id, duration, initTime, startTime, statusDetails
                 statusMessages, traceProfiles, resultsAvailable, resultSizeInBytes, tag, postprocessors, and targets.
        """
        return self._rd.get_all_trace_info(timeout=timeout)

    def get_all_bts_info(self, timeout=30):
        """
         Provides basic information about BTS in connected DCAP-LITE.

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return list[dict]: It returns list of dict with parameters `id`, `alias`, `name`, `mrBtsId`, `alias`,
                 `latitude`, `longitude`, `altitude`, `swVersion`, `type`, `host`, `port`, `password`, `username`,
                  `nrCells`, ` lteCells` and `internalTraceEnabled`.
        :raises `ApiException` if security authentication does not work.

        Example:

          [{
            "id": 0,
            "alias": "string",
            "name": "string",
            "mrBtsId": 0,
            "latitude": 0,
            "longitude": 0,
            "altitude": 0,
            "swVersion": "string",
            "type": "ENB",
            "host": "string",
            "port": 0,
            "password": "string",
            "username": "string",
            "nrCells": [
              "string"
            ],
            "lteCells": [
              "string"
            ],
            "internalTraceEnabled": true
          }, ...]
         """
        return self._rd.get_all_bts_info(timeout=timeout)

    def get_bts_by_id(self, bts_id=None, timeout=30):
        """
         Provides basic information about BTS in connected DCAP-LITE.

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :param str bts_id: bts id to get the info by id. Id will be returned from start_trace keyword.
        :return: It returns dict with parameters `id`, `alias`, `name`, `mrBtsId`, `alias`, `latitude`, `longitude`,
                 `altitude`, `swVersion`, `type`, `host`, `port`, `password`, `username`, `nrCells`, ` lteCells`
                  and `internalTraceEnabled`.
        :raises `ApiException` if security authentication does not work.

        Example:

          {
            "id": 0,
            "alias": "string",
            "name": "string",
            "mrBtsId": 0,
            "latitude": 0,
            "longitude": 0,
            "altitude": 0,
            "swVersion": "string",
            "type": "ENB",
            "host": "string",
            "port": 0,
            "password": "string",
            "username": "string",
            "nrCells": [
              "string"
            ],
            "lteCells": [
              "string"
            ],
            "internalTraceEnabled": true
          }
         """
        return self._rd.get_bts_by_id(bts_id=bts_id, timeout=timeout)

    def get_5g_profiles(self, timeout=30):
        """
        This method is used to get all 5G profiles info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: 5G trace profiles info.
        """
        return self._rd.get_5g_profiles(timeout=timeout)

    def get_lte_profiles(self, timeout=30):
        """
        This method is used to get all lte profiles info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: lte trace profiles info.
        """
        return self._rd.get_lte_profiles(timeout=timeout)

    def get_bts_profiles(self, timeout=30):
        """
        This method is used to get all bts profiles info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: bts trace profiles info.
        """
        return self._rd.get_bts_profiles(timeout=timeout)

    def get_tracers(self, timeout=30):
        """
        This method is used to get the traces info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: tracers info.
        """
        return self._rd.get_tracers(timeout=timeout)

    def abort_trace(self, trace_id=None, timeout=30):
        """
        This method is used to abort trace under DCAP-LITE

        :param str trace_id: trace id which has to be aborted. Id will be returned from start_trace keyword.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with aborted information
        """
        return self._rd.abort_trace(trace_id=trace_id, timeout=timeout)

    def get_vcu_profiles(self, timeout=30):
        """
        This method is used to get all vcu profiles info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: vcu trace profiles info.
        """
        return self._rd.get_vcu_profiles(timeout=timeout)

    def get_vdu_profiles(self, timeout=30):
        """
        This method is used to get all vdu profiles info under DCAP-LITE

        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: vdu trace profiles info.
        """
        return self._rd.get_vdu_profiles(timeout=timeout)

    def check_precondition(self, invalidate_bts_info_cache=None, bts=None, timeout=400, **kwargs):
        """
        This method is used to check pre-conditions to start a trace under DCAP-LITE

        :param bool invalidate_bts_info_cache: (optional)
            Controls whether to use the cached BTS info or fetch fresh data.
            * If not provided or is set to false, dry-run uses cache for BTS info requests.
            * Should be true if BTS configuration has been recently changed, like after a BTS configuration change.
            * With "invalidate_bts_info_cache": true, response time is about 10 seconds as BTS must be queried.
            * With false, it takes only milliseconds.
        :param dict bts: (required) dict of bts details containing host, username, password and port number to
                          start the trace for single bts.
                          The list of dict bts details containing host, username, password and port number to
                          start the trace for multiple bts.
        :param str tag: the tag of this StartTraceBody. default 'start_trace'
        :param float duration: The duration of this StartTraceBody duration in minutes.default infinite duration
        :param Union[int,str] timeout: (optional) Timeout to wait for "running" state, default=400s
        :param str kwargs:  supported params are as below:
        :param bool force: signifying whether the trace should force a shutdown of any previously running traces.
                       Defaults to true. If the trace startup finds an ongoing trace and 'force' is set to false,
                       the startup fails due to ongoing traces error. If the 'force' flag is set to true,
                       the startup first shuts down any ongoing traces and then continues with the startup,
                       default value is "True"
        :param str gnb_trace_profile: the id or name of the gNB (5G) start trace. user can get the gNB trace profile
                                      id or name details from `get_5g_profiles`.
        :param str enb_trace_profile: the id or name of the LTE (ENB) start trace. user can get the LTE trace profile
                                      id or name details from  `get_LTE_profiles`.
        :param str bts_trace_profile: the id or name of the BTS start trace. user can get the BTS trace profile
                                      id or name details from  `get_bts_profiles`.
        :param str vcu_trace_profile: the id or name of the vCU start trace. user can get the vCU trace profile
                                      id or name details from  `get_vcu_profiles`.
        :param str vdu_trace_profile: the id or name of the vDU start trace. user can get the vDU trace profile
                                      id or name details from  `get_vdu_profiles`.
        :param list gnb_custom_profile: The gNB (5G) custom profile name list of the start trace to be started.

                                         e.g : [pmFiles5g, condor5gSyslog, SCF5g,
                                         L2Ps_Component, L2Lo_Component, L2HiRlc_Component, L2HiPdcp_Component,
                                         L2Ps_Sherpa, L2Lo_Sherpa, L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         Tracer_5g,
                                         :ref:`l1IqTracer <l1IqTracer>`,
                                         :ref:`cp_5g <controlPlane5g>`,
                                         :ref:`controlPlane5g <controlPlane5g>`,
                                         :ref:`bip_interface_mirroring <bip_interface_mirroring>`,
                                         :ref:`L1stream <L1stream>`,
                                         :ref:`L2Ps_Component <L2Ps_Component>`]

        :param list enb_custom_profile: The LTE (ENB) custom profile name list of the start trace to be started.

                                         e.g : [lteTracer_4g, condor4gTti, condor4gAa, condor4gSyslog,
                                         pmFiles4g, scf4g, condor4gL2, l1Iq4g,
                                         :ref:`cp_4g <controlPlane4g>`,
                                         :ref:`controlPlane4g <controlPlane4g>`]

        :param list bts_custom_profile: The BTS custom profile name list of the start trace to be started.

                                         e.g : [scf, pmFiles,
                                         :ref:`rad <rad>`,
                                         :ref:`tss <tss>`,
                                         :ref:`immediateSnapshot <immediateSnapshot>`,
                                         :ref:`ipCapture <ipCapture>`,
                                         :ref:`screlBts <screlBts>`,
                                         :ref:`BTSeventBasedTracer <BTSeventBasedTracer>`]

        :param list vdu_custom_profile: The VDU custom profile name list of the start trace to be started.

                                         e.g : [snapshotVdu, tracerVdu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`L1StreamVdu <L1StreamVdu>`
                                         :ref:`flowTracerVdu <controlPlane5gVdu>`,
                                         :ref:`tssVdu <tssVdu>`,
                                         :ref:`controlPlane5gVdu <controlPlane5gVdu>`,
                                         :ref:`syslogVdu <syslogVdu>`,
                                         :ref:`l1IqVdu <l1IqVdu>`,
                                         :ref:`eventBasedTracerVdu <eventBasedTracerVdu>`,
                                         :ref:`screlVdu <screlVdu>`]

        :param list vcu_custom_profile: The VCU custom profile name list of the start trace to be started.
                                         e.g : [snapshotVcu, tracerVcu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`flowTracerVcu <controlPlane5gVcu>`
                                         :ref:`controlPlane5gVcu <controlPlane5gVcu>`,
                                         :ref:`syslogVcu <syslogVcu>`,
                                         :ref:`screlVcu <screlVcu>`]

        :param bool wait_for_activation: If user wants to confirm if the traces are started, and it is in "running"
                                    state. pass wait_for_activation=True
        :param str resource_group: 	you can pass "on-demand" or "inspector"
        :param bool allow_start_failures: If set to true trace will continue even on tracer errors, as long as one
                                          trace target is running. If set to false whole trace will fail if even single
                                          tracer fails. default value is "True"
        :param post_processors: (optional) by default false.
                                For emil decoding pass post_processors=True and emil_profile_values
                                The profiles can be "standard" Emil profile (like "5G L3") or custom, user created
                                profile? e.g. emil_profile_values='5G L3'

        :return: {msgs	[ErrorMessage Human readable error message as a single string]
                  ok	boolean True value indicates that trace can be started with provided values.}
        """
        return self._rd.check_precondition(invalidate_bts_info_cache=invalidate_bts_info_cache,
                                           bts=bts,
                                           timeout=timeout,
                                           **kwargs)

