    def get_decoded_file_contents(self, session_id, id_value, what, timeout=30):
        """
        This method returns the contents of Emil data rows from the decoded logs

        :param str session_id: Name of the session
        :param str id_value: Id of the session
        :param str what: Type of data to be returned. Possible values are:"calls" data rows from a call grid,
                         "source" data from the source specified by [idValue]
                         [trace id] data from a specific trace in the call grid identified by [idValue]
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: Returns data from call grid, source, or call trace. The response contains the contents of
                 Emil data rows from call grid window, source message window, or trace message window.Data can be
                 returned in json format.
        """
        return self._rd.get_decoded_file_contents(session_id=session_id,
                                                  id_value=id_value,
                                                  what=what,
                                                  timeout=timeout)

    def get_decoded_file_contents_in_json(self, session_id, data_source_id, what=None, timeout=30, **kwargs):
        """
        This method returns the contents of Emil data rows from the decoded logs

        :param str session_id: Name of the session
        :param str data_source_id: Identifier for the data source. A value that acts as grid id or source id,
                                   depending on the 'what' parameter
        :param str what: Type of data to be returned. Possible values are:"calls" data rows from a call grid,
                         "source" data from the source specified by [idValue]
                         [trace id] data from a specific trace in the call grid identified by [idValue],
                         default value is source
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s
        :param str kwargs:  supported params are as below:
        :param list[str] filter: Specifies condition that a data row must fulfill to be included in the results.
                           Conditions should be of form with either single or double quotes with comma separator
                           "[column name]"[comparison-operator]"constantvalue"/"constantvalue2"/...
                           If multiple values are given, the column content is compared against all of them and the
                           condition is satisfied if any comparison result is true.
                           Exception: with != operator the column content must not equal any of the given values.
                           Comparison operators = < > <= >= != are available. In addition, == can be used to check if
                           given string appears somewhere inside column value. The filter value may contain several
                           conditions separated by comma or semicolon. In this case, comma acts as AND operator,
                           semicolon as OR operator. They are evaluated left-to-right.
                           Example: filter='"ZMQ/SCTP name"="F1AP: ULRRCMessageTransfer","Mapping"="f1apPort"' or
                                    filter="'ZMQ/SCTP name'='F1AP: ULRRCMessageTransfer','Mapping'='f1apPort'"
        :param str/int rows: Defines the subset of data rows to be returned, e.g. 0-24
        :param str tree: Can be set to 'n' to indicate that MessageTree part should not be returned

        :return: Return of Emil data rows from the decoded logs in raw JSON string format.
        """
        return self._rd.get_decoded_file_contents_in_json(session_id=session_id,
                                                          data_source_id=data_source_id,
                                                          what=what,
                                                          timeout=timeout,
                                                          **kwargs)

