    def upload_decoding_profile(self, profile_name=None, profile_bases=None, profile_file_path=None, timeout=30):
        """
        Upload a decoding profile to the server

        **NOTE** To upload decoding profiles you will have to connect dcap with "nivuser" user
                 In the latest UTF default user is "nivuser" and password is "nivadmin!"

        :param str profile_name: Name(s) of the new profile directory(ies). They must match the directory names
                                 of zip file entries.
        :param str profile_bases: Name(s) of the base profile(s), if any
        :param str profile_file_path: Path to the profile zip file
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

         **NOTE**: the profile_name and profile_file_path zip name should match
        e.g: if profile_name="testprof" then zip file name should be same
             profile_file_path='/home/ute/testprof.zip'

        :return: list of tuple profile info
        """
        return self._rd.upload_decoding_profile(profile_name=profile_name,
                                                profile_bases=profile_bases,
                                                profile_file_path=profile_file_path,
                                                timeout=int(timeout))

    def list_session_files(self, session_id, keepalive, timeout):
        """
        This method provides the information about the contents of the given session

        :param str session_id: Name of the session
        :param str keepalive: (optional) sets new keepalive timer for the session. The value is interpreted
                              as number of hours.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return:
        """
        return self._rd.list_session_files(session_id=session_id,
                                           keepalive=keepalive,
                                           timeout=timeout)

    def download_session_file(self, session_id, file_name, target_dir, timeout):
        """
        This method is used to Download a file from the given session data directory

        :param str session_id: Name of the session
        :param str file_name: Name of the file to download
        :param str target_dir: (optional) local storage path for collected files, default path will be /tmp
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: Returns the contents of the given file (if it exists)
        """
        return self._rd.download_session_file(session_id=session_id,
                                              file_name=file_name,
                                              target_dir=target_dir,
                                              timeout=timeout)

